CREATE OR REPLACE FUNCTION cwm_touch_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN NEW.updated_at := now() AT TIME ZONE 'UTC'; RETURN NEW; END
$$;

